<!doctype html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="referrer" content="no-referrer"><title>{{ __('Sponsorenlauf | ClubUnio') }}</title><link rel="stylesheet" href="/css/sponsor-run.css"><script src="/js/sponsor-run-public.js?v=2" defer></script></head>
<body><main class="sr-public"><h1>{{ __('Sponsorenlauf') }}</h1><p id="sr-message" role="status"
    data-invalid-link="{{ __('Link ist ungültig oder abgelaufen.') }}"
