    data-event-deadline="{{ __(':date / Zusagefrist :deadline') }}"
    data-request-failed="{{ __('Anfrage fehlgeschlagen. Bitte erneut versuchen.') }}">{{ __('Link wird geprüft.') }}</p><section id="sr-event" hidden><h2 id="sr-title"></h2><p id="sr-alias"></p><p id="sr-date"></p></section>
<form id="sr-confirm" hidden><button type="submit">{{ __('Zusage verbindlich bestätigen') }}</button></form>
<form id="sr-pledge" hidden>
<label>{{ __('Sponsorname') }}<input name="sponsor_name" maxlength="160" required autocomplete="name"></label>
<fieldset><legend>{{ __('Zusage') }}</legend><label>{{ __('Art') }}<select name="amount_type"><option value="per_lap">{{ __('Pro Runde') }}</option><option value="fixed">{{ __('Fixbetrag') }}</option></select></label><label>{{ __('Betrag (CHF)') }}<input name="amount_chf" inputmode="decimal" maxlength="12" required></label><label>{{ __('Obergrenze (CHF)') }}<input name="cap_chf" inputmode="decimal" maxlength="12"></label></fieldset>
<fieldset><legend>{{ __('Rechnungsempfaenger') }}</legend><label>{{ __('Typ') }}<select name="recipient_type"><option value="person">{{ __('Person') }}</option><option value="company">{{ __('Firma') }}</option></select></label><label>{{ __('Firma') }}<input name="company" maxlength="160" autocomplete="organization"></label><label>{{ __('Vorname / Kontakt') }}<input name="first_name" maxlength="100" required autocomplete="given-name"></label><label>{{ __('Nachname') }}<input name="last_name" maxlength="100" required autocomplete="family-name"></label><label>{{ __('Strasse') }}<input name="street" maxlength="160" required autocomplete="address-line1"></label><label>{{ __('Hausnummer') }}<input name="house_number" maxlength="20"></label><label>{{ __('PLZ') }}<input name="postal_code" maxlength="20" required autocomplete="postal-code"></label><label>{{ __('Ort') }}<input name="city" maxlength="100" required autocomplete="address-level2"></label><label>{{ __('Land (ISO)') }}<input name="country" minlength="2" maxlength="2" pattern="[A-Z]{2}" value="CH" required autocomplete="country"></label><label>{{ __('E-Mail') }}<input name="email" type="email" maxlength="254" required autocomplete="email"></label></fieldset>
<label class="sr-trap" aria-hidden="true">{{ __('Website') }}<input name="website" tabindex="-1" autocomplete="off"></label>
<label class="sr-consent"><input type="checkbox" name="consent" required> {{ __('Ich stimme der Verarbeitung meiner Angaben für diese Sponsorenzusage und Rechnung zu und bestätige die Zusage nach E-Mail-Bestätigung.') }}</label><button type="submit">{{ __('Bestätigung anfordern') }}</button></form>
</main></body></html>
